import{_ as t,o,c as a,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Automation — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Automation — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/automation"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Automation — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/automation"}]]},"headers":[],"relativePath":"developer-guide/automation.md","filePath":"developer-guide/automation.md","lastUpdated":1787698998000}'),i={name:"developer-guide/automation.md"};function n(r,e,c,s,l,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="automation-—-developer-guide" tabindex="-1">Automation — Developer Guide <a class="header-anchor" href="#automation-—-developer-guide" aria-label="Permalink to &quot;Automation — Developer Guide&quot;">​</a></h1><p>Billable marketplace module (<code>automation</code> v1.0.0). Mirrors Tasks packaging; domain logic lives in a cross-module engine that subscribes to existing domain events.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>app/Models/Automation{Workflow,Trigger,Condition,Action,Run,Log}.php</code></td></tr><tr><td>Enums</td><td><code>AutomationRunStatusEnum</code>, <code>AutomationConditionOperatorEnum</code>, <code>AutomationLogLevelEnum</code></td></tr><tr><td>Services</td><td><code>app/Services/Tenant/Automation/*</code> (<code>WorkflowService</code>, <code>AutomationEngine</code>, <code>ConditionEvaluator</code>, <code>ActionRunner</code>, registries, handlers)</td></tr><tr><td>Bridge</td><td><code>Listeners/AutomationEventBridge</code> (registered in <code>AppServiceProvider</code>)</td></tr><tr><td>Job</td><td><code>ExecuteAutomationRunJob</code> on queue <code>automations</code></td></tr><tr><td>Schedule</td><td><code>automation:dispatch-schedules</code> every minute</td></tr><tr><td>Controllers</td><td><code>AutomationWorkflowController</code>, <code>AutomationRunController</code>, <code>AutomationCatalogController</code>, <code>AutomationTemplateController</code></td></tr><tr><td>Policies</td><td><code>AutomationWorkflowPolicy</code>, <code>AutomationRunPolicy</code></td></tr><tr><td>Notification</td><td><code>AutomationWorkflowNotification</code> (<code>NotificationSourceEnum::Workflow</code>)</td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Automation/*</code>, <code>tests/Unit/Automation/*</code></td></tr></tbody></table><h2 id="activation-gate" tabindex="-1">Activation gate <a class="header-anchor" href="#activation-gate" aria-label="Permalink to &quot;Activation gate&quot;">​</a></h2><p>Workflows are always persisted <strong>inactive</strong>. Create/update with <code>is_active=true</code> still saves first, then calls <code>activate()</code>. Unwired catalog triggers (for example <code>contact.created</code>) cannot be activated — the row stays inactive and the API returns validation errors on <code>trigger</code>.</p><h2 id="loop-guard-notification-source" tabindex="-1">Loop guard &amp; notification source <a class="header-anchor" href="#loop-guard-notification-source" aria-label="Permalink to &quot;Loop guard &amp; notification source&quot;">​</a></h2><ul><li>While <code>AutomationContext</code> depth &gt; 0, <code>AutomationEngine::dispatchEvent()</code> no-ops so action side-effects do not recurse.</li><li>Mentions / DMs use <code>NotificationSourceEnum::Mention</code> and <code>DirectMessage</code>. Reserve <code>Workflow</code> for Automation-fired notifications.</li></ul><h2 id="trigger-action-registries" tabindex="-1">Trigger / action registries <a class="header-anchor" href="#trigger-action-registries" aria-label="Permalink to &quot;Trigger / action registries&quot;">​</a></h2><p>Modules publish metadata via <code>AutomationTriggerRegistry</code> and <code>AutomationActionRegistry</code> (singletons with <code>registerDefaults()</code>).<br><code>wired=false</code> stubs appear in the catalog but cannot be activated.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>automation.view | create | update | delete | run | manage_logs</span></span></code></pre></div><p>Routes: <code>module:automation</code> then <code>can:automation.*</code>.</p><h2 id="date-and-time" tabindex="-1">Date and time <a class="header-anchor" href="#date-and-time" aria-label="Permalink to &quot;Date and time&quot;">​</a></h2><p>Schedule evaluation uses workspace timezone from <code>TenantSettingService</code> — see <a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone convention</a>. Daily/weekly/monthly times match within 90 seconds after <code>H:i</code>; duplicate schedule runs for the same workflow are suppressed for 2 minutes.</p><h2 id="outbound-webhooks" tabindex="-1">Outbound webhooks <a class="header-anchor" href="#outbound-webhooks" aria-label="Permalink to &quot;Outbound webhooks&quot;">​</a></h2><p><code>OutboundWebhookService</code> blocks private/loopback hosts (SSRF). Optional HMAC via <code>AUTOMATION_WEBHOOK_SECRET</code>. Exhausted <code>ExecuteAutomationRunJob</code> retries call <code>failed()</code> and persist run status <code>failed</code>. The job uses a per-run cache lock (so delay continuations wait instead of overlapping) and <code>$timeout = 60</code> (below Redis <code>retry_after</code> 90). Action <code>delay_seconds</code> is capped at 86400.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Pages</td><td><code>src/pages/automation/*</code></td></tr><tr><td>API</td><td><code>automationService</code> in <code>src/api/services.ts</code></td></tr><tr><td>Nav / routes</td><td><code>module: &#39;automation&#39;</code>, <code>/automation*</code></td></tr><tr><td>E2E</td><td><code>npm run test:e2e:automation</code></td></tr></tbody></table><h2 id="explicit-non-goals" tabindex="-1">Explicit non-goals <a class="header-anchor" href="#explicit-non-goals" aria-label="Permalink to &quot;Explicit non-goals&quot;">​</a></h2><p>Marketing Automation, Branch / commercial document generators — deferred. WhatsApp Cloud trigger <code>whatsapp.message_received</code> and action <code>send_whatsapp_template</code> shipped in Automation <strong>1.1.0</strong> / WhatsApp Cloud <strong>1.2.0</strong>.</p>',21)])])}const h=t(i,[["render",n]]);export{p as __pageData,h as default};
